const inp = $input.first().json;
const subj = String((inp && inp.subject) || '').substring(0, 200);
const body = String((inp && inp.body) || '').substring(0, 800);
const from = String((inp && inp.from) || '').substring(0, 200);
const out = {
  json: {
    jevBody: JSON.stringify({
      model: 'typesafe/jev-1.13',
      state: { context: 'Subject: ' + subj + ' | From: ' + from + ' | Body: ' + body },
      questions: {
        q1: { type: 'choice', prompt: 'Is this email spam?', options: ['spam','not_spam'], criteria: { spam: { weight: 1.0 }, not_spam: { weight: 1.0 } }, instructions: 'Analyze subject, sender, content. Spam if unsolicited/promotional/phishing.' },
        q2: { type: 'score', prompt: 'How urgent? (0 not urgent, 1 extremely urgent)', min: 0, max: 1, criteria: [{ weight: 1.0 }], instructions: 'Consider time-sensitive keywords.' },
        q3: { type: 'choice', prompt: 'What category?', options: ['work','personal','finance','other'], criteria: { work: { weight: 1.0 }, personal: { weight: 1.0 }, finance: { weight: 1.0 }, other: { weight: 1.0 } }, instructions: 'work=job; personal=social/family; finance=money; other=rest.' }
      }
    })
  }
};
return out;

// Apply Gmail labels via IMAP STORE +X-GM-LABELS.SILENT
// Credentials hardcoded for now (TODO: move to n8n credential via helpers.getCredentials when fixed)
const IMAP_USER = '${IMAP_USER}';
const IMAP_PASSWORD = '${IMAP_APP_PASSWORD}';
const IMAP_HOST = 'imap.gmail.com';
const IMAP_PORT = 993;

const item = $input.first();
const data = item.json;
const is_spam = data.is_spam;
const urgency = data.urgency;
const category = data.category;

const labels = [];
if (is_spam === 'spam') labels.push('Spam');
if (typeof urgency === 'number' && urgency >= 0.7) labels.push('Urgent');
if (category === 'work') labels.push('Work');
else if (category === 'personal') labels.push('Personal');
else if (category === 'finance') labels.push('Finance');
else if (category === 'other') labels.push('Other');

const uid = data.messageUid || data.uid || (item.binary && item.binary.messageUid);

if (!uid) {
  return [{
    json: {
      ...data,
      _labels_applied: [],
      _labels_skipped: labels,
      _skip_reason: 'no_uid_webhook_path',
    },
  }];
}

const tls = require('tls');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const imapCommand = (socket, tag, command) => new Promise((resolve, reject) => {
  socket.write(tag + ' ' + command + '\r\n');
  const onData = (chunk) => {
    let text = chunk.toString();
    let idx;
    while ((idx = text.indexOf('\r\n')) >= 0) {
      const line = text.substring(0, idx);
      const rest = text.substring(idx + 2);
      if (line.startsWith('* ') || line.startsWith('+ ')) {
        text = rest;
        if (text.length > 0) continue;
        return;
      }
      const m = line.match(/^([A-Z]\d+) (OK|NO|BAD)(.*)?$/);
      if (m && m[1] === tag) {
        socket.off('data', onData);
        if (m[2] === 'OK') resolve();
        else reject(new Error('IMAP ' + m[2] + (m[3] || '')));
        return;
      }
      text = rest;
      if (text.length > 0) continue;
      return;
    }
  };
  socket.on('data', onData);
});

const socket = tls.connect({ host: IMAP_HOST, port: IMAP_PORT, rejectUnauthorized: true });
const result = { uid, applied: [], skipped: labels.slice() };
try {
  await new Promise((resolve, reject) => {
    socket.once('error', reject);
    socket.once('connect', resolve);
  });
  await sleep(200);
  const authPayload = Buffer.concat([Buffer.from('\0' + IMAP_USER + '\0' + IMAP_PASSWORD)]).toString('base64');
  await imapCommand(socket, 'A001', 'AUTHENTICATE PLAIN ' + authPayload);
  await sleep(300);
  await imapCommand(socket, 'A002', 'SELECT INBOX');
  await sleep(200);
  if (labels.length > 0) {
    const labelsList = labels.map((l) => '"' + l + '"').join(' ');
    await imapCommand(socket, 'A003', 'UID STORE ' + uid + ' +X-GM-LABELS.SILENT (' + labelsList + ')');
    await sleep(200);
    result.applied = labels.slice();
    result.skipped = [];
  }
  await imapCommand(socket, 'A004', 'UID STORE ' + uid + ' +FLAGS.SILENT (\\Seen)');
  await sleep(200);
  await imapCommand(socket, 'A005', 'LOGOUT');
} catch (e) {
  result.error = e.message;
} finally {
  socket.end();
}

return [{
  json: {
    ...data,
    _labels_applied: result.applied,
    _labels_skipped: result.skipped,
    _uid: uid,
    _im_error: result.error || null,
  },
}];

